    const int tile_j = 32;  // tile size in j (x)
    const int tile_i = 32;  // tile size in i (y)
    const int vec    = 8;   // SIMD width for j

    // Compute entire result at root.
    syr2k
        .compute_root()
        // Tile (j, i) into (jo, io) outer tiles and (ji, ii) inner coords.
        .tile(j, i, jo, io, ji, ii, tile_j, tile_i)
        // Parallelize across tile rows (io) to use many CPU cores.
        .parallel(io)
        // Vectorize across contiguous j within each tile.
        .vectorize(ji, vec);

    // Schedule for the reduction update.
    // After tiling, the update definition sees the same split Vars.
    // We order loops as:
    //   for io (parallel)
    //     for jo
    //       for ii
    //         for ji (vectorized)
    //           for k (reduction over columns of A/B)
    //
    // Keeping (j,i) loops inside k preserves the algorithmic structure
    // (for each (i,j) accumulate over k) while still giving good
    // spatial locality and SIMD over j.
    syr2k.update()
        .reorder(ji, ii, k, jo, io) // ji innermost, then ii, then k, etc.
        .parallel(io)
        .vectorize(ji, vec);

    // JIT-compile the kernel
    syr2k.compile_jit();

    // Time the execution
    auto start = std::chrono::high_resolution_clock::now();

    // Run kernel: write result back into C (in-place update of C)
    syr2k.realize(C);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally print the result (mainly to prevent dead-code elimination
    // and to allow correctness checking if desired).
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int ii = 0; ii < n; ii++) {
            for (int jj = 0; jj < n; jj++) {
                // Recall: C(ii,jj) in C maps to C(jj,ii) in Buffer
                std::cerr << C(jj, ii) << '\n';
            }
        }
    }

    std::cout << std::fixed << std::setprecision(6);
